package com.nexttv;
import android.app.*;import android.content.*;import android.os.*;import android.view.KeyEvent;import android.view.accessibility.AccessibilityNodeInfo;
public class MenuContentInstrumentation extends com.nexttv.support.NextTvInstrumentation {
 private Activity activity;private int passed;private final StringBuilder results=new StringBuilder();
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}

 private void launch()throws Exception{activity=startActivitySync(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setClassName("com.nexttv","com.nexttv.core.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));text("频道分类：");SystemClock.sleep(2300);}
 private void closeEditor()throws Exception{key(KeyEvent.KEYCODE_ESCAPE);SystemClock.sleep(400);if(tree().contains("保存"))key(KeyEvent.KEYCODE_ESCAPE);SystemClock.sleep(250);}
 private void pass(String name){passed++;results.append("PASS ").append(name).append('\n');Bundle b=new Bundle();b.putString("stream","PASS "+name+"\n");sendStatus(0,b);}


 private void reopen(){try(android.os.ParcelFileDescriptor fd=getUiAutomation().executeShellCommand("am start -a android.intent.action.MAIN -c android.intent.category.LAUNCHER -f 0x10200000 -n com.nexttv/com.nexttv.core.tv.TvActivity")){java.io.FileInputStream input=new java.io.FileInputStream(fd.getFileDescriptor());byte[] buffer=new byte[1024];while(input.read(buffer)>=0){}}catch(Exception e){throw new RuntimeException(e);}}
 private void shot(String name)throws Exception{android.graphics.Bitmap image=getUiAutomation().takeScreenshot();if(image!=null){try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(getTargetContext().getFilesDir(),"fix13-"+name+".png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}}
 @Override public void onStart(){try{getTargetContext().getSharedPreferences("nexttv",0).edit().putString("selected_group","").commit();
 launch();await("initial Channels focus",()->focus().equals("频道"));shot("home-nav");key(KeyEvent.KEYCODE_DPAD_DOWN);await("channel header",()->focus().startsWith("频道分类："));key(KeyEvent.KEYCODE_DPAD_DOWN);await("channel card",()->focus().contains("CCTV1综合"));shot("home-first-card");key(KeyEvent.KEYCODE_DPAD_LEFT);if(!focus().contains("CCTV1综合"))throw new IllegalStateException("Left edge crossed content region");key(KeyEvent.KEYCODE_DPAD_UP);await("grid returns header",()->focus().startsWith("频道分类："));key(KeyEvent.KEYCODE_DPAD_UP);await("header returns own menu",()->focus().equals("频道"));pass("Channels menu → header → first card → header → Channels, no left wrap");
 key(KeyEvent.KEYCODE_DPAD_RIGHT);key(KeyEvent.KEYCODE_DPAD_DOWN);await("favorites header",()->(!focus().equals("收藏")||tree().contains("还没有收藏频道")));key(KeyEvent.KEYCODE_DPAD_UP);await("favorites own menu",()->focus().equals("收藏"));if(!tree().contains("我的收藏"))throw new IllegalStateException("Page and focus disagree");pass("Favorites content returns to Favorites without selecting Channels");
 key(KeyEvent.KEYCODE_DPAD_RIGHT);key(KeyEvent.KEYCODE_DPAD_DOWN);await("settings first item",()->focus().contains("节目单地址"));shot("settings-focus");key(KeyEvent.KEYCODE_DPAD_DOWN);await("second settings item",()->focus().contains("立即更新节目单"));key(KeyEvent.KEYCODE_DPAD_UP);await("first item",()->focus().contains("节目单地址"));key(KeyEvent.KEYCODE_DPAD_UP);await("settings own menu",()->focus().equals("设置"));key(KeyEvent.KEYCODE_DPAD_DOWN);await("settings remembers prior row",()->focus().contains("节目单地址"));key(KeyEvent.KEYCODE_BACK);await("Back returns Settings nav",()->focus().equals("设置"));pass("Settings rows and top menu use real D-pad handoff and Back");
 for(int i=0;i<4;i++){key(KeyEvent.KEYCODE_DPAD_LEFT);await("favorites after left",()->focus().equals("收藏")&&tree().contains("我的收藏"));key(KeyEvent.KEYCODE_DPAD_LEFT);await("channels after left",()->focus().equals("频道")&&tree().contains("频道分类："));key(KeyEvent.KEYCODE_DPAD_RIGHT);key(KeyEvent.KEYCODE_DPAD_RIGHT);await("settings after rapid right",()->focus().equals("设置")&&tree().contains("节目单地址"));}pass("Repeated three-menu switching keeps actual focus and visible page aligned");
 Bundle b=new Bundle();b.putString("stream",results+"Menu/content: "+passed+" groups passed\n");finish(Activity.RESULT_OK,b);
 }catch(Throwable t){Bundle b=new Bundle();b.putString("stream",t.toString());finish(Activity.RESULT_CANCELED,b);}}
}
